// NULL-tolerant scan buffer for workoutScanMapperNullable:
// on a LEFT JOIN miss every column comes back NULL, so each field uses the
// nullable version of the column type even when the column itself is NOT NULL.
type workoutPreloadBuf struct {
	ID         null.Val[string]
	UserID     null.Val[string]
	FinishedAt null.Val[time.Time]
	CreatedAt  null.Val[time.Time]
	Name       null.Val[string]
	StartedAt  null.Val[time.Time]
	Note       null.Val[string]
	RoutineID  null.Val[string]
}

// workoutScanMapperNullable maps the preloaded workout
// columns (prefixed with the runtime join alias) without reflection, while
// keeping the LEFT JOIN semantics of the reflection-based mapper: a row whose
// prefixed columns are all NULL yields nil (no child), and NULL values never
// error, they just leave the zero value in the field.
func workoutScanMapperNullable(prefix string) scan.Mapper[*Workout] {
	return func(ctx context.Context, cols []string) (scan.BeforeFunc, func(any) (*Workout, error)) {
		// resolve the column names once per query, not per row
		type target struct {
			idx int
			dst func(b *workoutPreloadBuf) any
		}
		targets := make([]target, 0, 8)
		for i, col := range cols {
			name, ok := strings.CutPrefix(col, prefix)
			if !ok {
				continue
			}
			switch name {
			case "id":
				targets = append(targets, target{i, func(b *workoutPreloadBuf) any { return &b.ID }})
			case "user_id":
				targets = append(targets, target{i, func(b *workoutPreloadBuf) any { return &b.UserID }})
			case "finished_at":
				targets = append(targets, target{i, func(b *workoutPreloadBuf) any { return &b.FinishedAt }})
			case "created_at":
				targets = append(targets, target{i, func(b *workoutPreloadBuf) any { return &b.CreatedAt }})
			case "name":
				targets = append(targets, target{i, func(b *workoutPreloadBuf) any { return &b.Name }})
			case "started_at":
				targets = append(targets, target{i, func(b *workoutPreloadBuf) any { return &b.StartedAt }})
			case "note":
				targets = append(targets, target{i, func(b *workoutPreloadBuf) any { return &b.Note }})
			case "routine_id":
				targets = append(targets, target{i, func(b *workoutPreloadBuf) any { return &b.RoutineID }})
			}
		}

		// One scratch buffer reused for every row: before -> scan -> after runs
		// synchronously per row, the scheduled columns are fully overwritten each
		// row, and unselected columns stay zero, so a single buffer preserves the
		// per-row NULL semantics without allocating a buffer per parent row. The
		// returned child (o below) is always freshly allocated, so buf never
		// escapes past the after func.
		buf := new(workoutPreloadBuf)
		return func(row *scan.Row) (any, error) {
				for _, t := range targets {
					row.ScheduleScanByIndex(t.idx, t.dst(buf))
				}
				return buf, nil
			}, func(link any) (*Workout, error) {
				buf := link.(*workoutPreloadBuf)

				// Same rule as the reflection mapper's row validator: the child
				// exists only if at least one of its columns is not NULL. Columns
				// not selected by the query are never scanned and stay invalid,
				// so this check also matches when only a subset is selected.
				if !(buf.ID.IsValue()) &&
					!(buf.UserID.IsValue()) &&
					!(buf.FinishedAt.IsValue()) &&
					!(buf.CreatedAt.IsValue()) &&
					!(buf.Name.IsValue()) &&
					!(buf.StartedAt.IsValue()) &&
					!(buf.Note.IsValue()) &&
					!(buf.RoutineID.IsValue()) {
					return nil, nil
				}

				o := new(Workout)
				if buf.ID.IsValue() {
					o.ID = buf.ID.MustGet()
				}
				if buf.UserID.IsValue() {
					o.UserID = buf.UserID.MustGet()
				}
				if buf.FinishedAt.IsValue() {
					o.FinishedAt = buf.FinishedAt.MustGet()
				}
				if buf.CreatedAt.IsValue() {
					o.CreatedAt = buf.CreatedAt.MustGet()
				}
				if buf.Name.IsValue() {
					o.Name = buf.Name.MustGet()
				}
				if buf.StartedAt.IsValue() {
					o.StartedAt = buf.StartedAt.MustGet()
				}
				o.Note = buf.Note
				o.RoutineID = buf.RoutineID
				return o, nil
			}
	}
}

func (o *Workout) Preload(name string, retrieved any) error {
	if o == nil {
		return nil
	}

	switch name {
	case "Sets":
		rels, ok := retrieved.(SetSlice)
		if !ok {
			return fmt.Errorf("workout cannot load %T as %q", retrieved, name)
		}

		o.R.Sets = rels
		o.R.Loaded.Sets = true

		for _, rel := range rels {
			if rel != nil {
				rel.R.Workout = o
				rel.R.Loaded.Workout = true
			}
		}
		return nil
	case "WorkoutComments":
		rels, ok := retrieved.(WorkoutCommentSlice)
		if !ok {
			return fmt.Errorf("workout cannot load %T as %q", retrieved, name)
		}

		o.R.WorkoutComments = rels
		o.R.Loaded.WorkoutComments = true

		for _, rel := range rels {
			if rel != nil {
				rel.R.Workout = o
				rel.R.Loaded.Workout = true
			}
		}
		return nil
	case "Routine":
		rel, ok := retrieved.(*Routine)
		if !ok {
			return fmt.Errorf("workout cannot load %T as %q", retrieved, name)
		}

		o.R.Routine = rel
		o.R.Loaded.Routine = true

		if rel != nil {
			rel.R.Workouts = WorkoutSlice{o}
		}
		return nil
	case "User":
		rel, ok := retrieved.(*User)
		if !ok {
			return fmt.Errorf("workout cannot load %T as %q", retrieved, name)
		}

		o.R.User = rel
		o.R.Loaded.User = true

		if rel != nil {
			rel.R.Workouts = WorkoutSlice{o}
		}
		return nil
	default:
		return fmt.Errorf("workout has no relationship %q", name)
	}
}

type workoutPreloader struct {
	Routine func(...psql.PreloadOption) psql.Preloader
	User    func(...psql.PreloadOption) psql.Preloader
}

func buildWorkoutPreloader() workoutPreloader {
	return workoutPreloader{
		Routine: func(opts ...psql.PreloadOption) psql.Preloader {
			return psql.Preload[*Routine, RoutineSlice](psql.PreloadRel{
				Name: "Routine",
				Sides: []psql.PreloadSide{
					{
						From:        Workouts,
						To:          Routines,
						FromColumns: []string{"routine_id"},
						ToColumns:   []string{"id"},
					},
				},
			}, Routines.Columns.Names(), routineScanMapperNullable, opts...)
		},
		User: func(opts ...psql.PreloadOption) psql.Preloader {
			return psql.Preload[*User, UserSlice](psql.PreloadRel{
				Name: "User",
				Sides: []psql.PreloadSide{
					{
						From:        Workouts,
						To:          Users,
						FromColumns: []string{"user_id"},
						ToColumns:   []string{"id"},
					},
				},
			}, Users.Columns.Names(), userScanMapperNullable, opts...)
		},
	}
}

