// LoadSets loads the workout's Sets into the .R struct
func (o *Workout) LoadSets(ctx context.Context, exec bob.Executor, mods ...bob.Mod[*dialect.SelectQuery]) error {
	if o == nil {
		return nil
	}

	// Reset the relationship
	o.R.Sets = nil
	o.R.Loaded.Sets = false

	related, err := o.Sets(mods...).All(ctx, exec)
	if err != nil {
		return err
	}

	for _, rel := range related {
		rel.R.Workout = o
		rel.R.Loaded.Workout = true
	}

	o.R.Sets = related
	o.R.Loaded.Sets = true
	return nil
}

// LoadSets loads the workout's Sets into the .R struct
func (os WorkoutSlice) LoadSets(ctx context.Context, exec bob.Executor, mods ...bob.Mod[*dialect.SelectQuery]) error {
	if len(os) == 0 {
		return nil
	}

	sets, err := os.Sets(mods...).All(ctx, exec)
	if err != nil {
		return err
	}

	for _, o := range os {
		if o == nil {
			continue
		}

		o.R.Sets = nil
		o.R.Loaded.Sets = true
	}
	// O(N+M) stitch via a map keyed by the join column (key -> []parent; was O(N*M)).
	workoutByKey := make(map[string][]*Workout, len(os))
	for _, o := range os {
		if o == nil {
			continue
		}

		workoutByKey[o.ID] = append(workoutByKey[o.ID], o)
	}

	for _, rel := range sets {

		owners, ok := workoutByKey[rel.WorkoutID]
		if !ok {
			continue
		}

		for _, o := range owners {

			rel.R.Workout = o
			rel.R.Loaded.Workout = true

			o.R.Sets = append(o.R.Sets, rel)

		}
	}

	return nil
}

