// LoadRoutine loads the workout's Routine into the .R struct
func (os WorkoutSlice) LoadRoutine(ctx context.Context, exec bob.Executor, mods ...bob.Mod[*dialect.SelectQuery]) error {
	if len(os) == 0 {
		return nil
	}

	routines, err := os.Routine(mods...).All(ctx, exec)
	if err != nil {
		return err
	}

	for _, o := range os {
		if o == nil {
			continue
		}

		o.R.Routine = nil
		o.R.Loaded.Routine = true
	}
	// O(N+M) stitch via a map keyed by the join column (key -> []parent; was O(N*M)).
	workoutByKey := make(map[string][]*Workout, len(os))
	for _, o := range os {
		if o == nil {
			continue
		}

		// NULL never matches any row in SQL, so don't add it to the map
		if !o.RoutineID.IsValue() {
			continue
		}

		workoutByKey[o.RoutineID.MustGet()] = append(workoutByKey[o.RoutineID.MustGet()], o)
	}

	for _, rel := range routines {

		owners, ok := workoutByKey[rel.ID]
		if !ok {
			continue
		}

		for _, o := range owners {

			// to-one: keep only the first matching child (matches the previous break)
			if o.R.Routine != nil {
				continue
			}

			rel.R.Workouts = append(rel.R.Workouts, o)

			o.R.Routine = rel

		}
	}

	return nil
}

