type workoutJoins[Q dialect.Joinable] struct {
	typ             string
	Sets            modAs[Q, setColumns]
	WorkoutComments modAs[Q, workoutCommentColumns]
	Routine         modAs[Q, routineColumns]
	User            modAs[Q, userColumns]
}

func (j workoutJoins[Q]) aliasedAs(alias string) workoutJoins[Q] {
	return buildWorkoutJoins[Q](buildWorkoutColumns(alias), j.typ)
}

func buildWorkoutJoins[Q dialect.Joinable](cols workoutColumns, typ string) workoutJoins[Q] {
	return workoutJoins[Q]{
		typ: typ,
		Sets: modAs[Q, setColumns]{
			c: Sets.Columns,
			f: func(to setColumns) bob.Mod[Q] {
				mods := make(mods.QueryMods[Q], 0, 1)

				{
					mods = append(mods, dialect.Join[Q](typ, Sets.NameExpr().As(to.Alias())).On(
						to.WorkoutID.EQ(cols.ID),
					))
				}

				return mods
			},
		},
		WorkoutComments: modAs[Q, workoutCommentColumns]{
			c: WorkoutComments.Columns,
			f: func(to workoutCommentColumns) bob.Mod[Q] {
				mods := make(mods.QueryMods[Q], 0, 1)

				{
					mods = append(mods, dialect.Join[Q](typ, WorkoutComments.NameExpr().As(to.Alias())).On(
						to.WorkoutID.EQ(cols.ID),
					))
				}

				return mods
			},
		},
		Routine: modAs[Q, routineColumns]{
			c: Routines.Columns,
			f: func(to routineColumns) bob.Mod[Q] {
				mods := make(mods.QueryMods[Q], 0, 1)

				{
					mods = append(mods, dialect.Join[Q](typ, Routines.NameExpr().As(to.Alias())).On(
						to.ID.EQ(cols.RoutineID),
					))
				}

				return mods
			},
		},
		User: modAs[Q, userColumns]{
			c: Users.Columns,
			f: func(to userColumns) bob.Mod[Q] {
				mods := make(mods.QueryMods[Q], 0, 1)

				{
					mods = append(mods, dialect.Join[Q](typ, Users.NameExpr().As(to.Alias())).On(
						to.ID.EQ(cols.UserID),
					))
				}

				return mods
			},
		},
	}
}
